    margin-bottom: 1.2rem;
}

.step__connector--completed {
    background: #2ecc71;
}

.step--future .step__number {
    opacity: 0.5;
}

.step--future .step__label {
    opacity: 0.5;
}

/* Step Content */
.step-content {
    background: white;
    border-radius: 8px;
    padding: 2rem;
    box-shadow: 0 2px 8px rgba(0, 0, 0, 0.08);
}

.step-content h2 {
    margin-bottom: 1.5rem;
    color: #1a1a2e;
    border-bottom: 2px solid #f0f0f0;
    padding-bottom: 0.75rem;
}

/* Form Elements */
.form-group {
    margin-bottom: 1.25rem;
}

.form-group label {
    display: block;
    margin-bottom: 0.4rem;
    font-weight: 500;
    color: #333;
    font-size: 0.9rem;
}

.form-group input,
.form-group textarea,
.form-group select {
    width: 100%;
    padding: 0.6rem 0.8rem;
    border: 1px solid #ddd;
    border-radius: 4px;
    font-size: 0.95rem;
    transition: border-color 0.2s;
    box-sizing: border-box;
}

.form-group input:focus,
.form-group textarea:focus {
    outline: none;
    border-color: #4361ee;
    box-shadow: 0 0 0 2px rgba(67, 97, 238, 0.1);
}

.form-row {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 1rem;
}

.checkbox-label {
    display: inline-flex !important;
    align-items: center;
    gap: 0.5rem;
    margin-top: 0.5rem;
    font-weight: normal !important;
    cursor: pointer;
}

.checkbox-label input[type="checkbox"] {
    width: auto;
}

.field-error {
    color: #e74c3c;
    font-size: 0.85rem;
    margin-top: 0.25rem;
    display: block;
}

.character-count {
    display: block;
    text-align: right;
    font-size: 0.85rem;
    color: #666;
    margin-top: 0.4rem;
}

.character-count--warning {
    color: #e67e22;
    font-weight: 500;
}

/* Buttons */
.btn {
    padding: 0.6rem 1.5rem;
    border: none;
    border-radius: 4px;
    font-size: 0.95rem;
    font-weight: 500;
    cursor: pointer;
    transition: all 0.2s;
    text-decoration: none;
}

.btn:disabled {
    opacity: 0.6;
    cursor: not-allowed;
}

.btn--primary {
    background: #4361ee;
    color: white;
}

.btn--primary:hover:not(:disabled) {
    background: #3451d1;
}

.btn--outline {
    background: white;
    color: #4361ee;
    border: 1px solid #4361ee;
}

.btn--outline:hover:not(:disabled) {
    background: #f0f4ff;
}

.btn--secondary {
    background: #f8f9fa;
    color: #495057;
    border: 1px dashed #adb5bd;
}

.btn--secondary:hover {
    background: #e9ecef;
}

.btn--danger {
    background: #fee;
    color: #e74c3c;
    border: 1px solid #fcc;
}

.btn--danger:hover {
    background: #fdd;
}

.btn--small {
    padding: 0.3rem 0.8rem;
    font-size: 0.8rem;
}

.btn--large {
    padding: 0.8rem 2rem;
    font-size: 1.1rem;
}

.btn--link {
    background: none;
    border: none;
    color: #4361ee;
    padding: 0;
    font-size: 0.9rem;
    text-decoration: underline;
    cursor: pointer;
}

.btn--link:hover {
    color: #3451d1;
}

/* Step Actions */
.step-actions {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-top: 2rem;
    padding-top: 1.5rem;
    border-top: 1px solid #f0f0f0;
}

/* Alerts */
.alert {
    padding: 1rem 1.25rem;
    border-radius: 4px;
    margin-bottom: 1.5rem;
}

.alert--error {
    background: #fef0f0;
    border: 1px solid #fcc;
    color: #c0392b;
}

.alert--success {
    background: #f0fef4;
    border: 1px solid #b7e4c7;
    color: #1b7340;
}

.alert--success h3 {
    margin: 0 0 0.5rem 0;
    border: none;
    padding: 0;
}

/* Work Entry & Reference Entry */
.work-entry,
.reference-entry {
    border: 1px solid #e9ecef;
    border-radius: 6px;
    padding: 1.25rem;
    margin-bottom: 1rem;
    background: #fafbfc;
}

.work-entry__header,
.reference-entry__header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 1rem;
}

.work-entry__header h4,
.reference-entry__header h4 {
    margin: 0;
    color: #495057;
}

/* Review Section */
.review-section {
    margin-bottom: 1.5rem;
    border: 1px solid #e9ecef;
    border-radius: 6px;
    padding: 1.25rem;
}

.review-section__header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 1rem;
}

.review-section__header h3 {
    margin: 0;
    border: none;
    padding: 0;
    font-size: 1.1rem;
}

.review-list {
    display: grid;
    grid-template-columns: 120px 1fr;
    gap: 0.5rem 1rem;
    margin: 0;
}

.review-list dt {
    font-weight: 500;
    color: #666;
}

.review-list dd {
    margin: 0;
}

.review-work-entry,
.review-reference {
    padding: 0.75rem 0;
    border-bottom: 1px solid #f0f0f0;
}

.review-work-entry:last-child,
.review-reference:last-child {
    border-bottom: none;
}

.review-cover-letter {
    white-space: pre-wrap;
    background: #f8f9fa;
    padding: 1rem;
    border-radius: 4px;
    margin: 0;
}

/* Responsive */
@media (max-width: 600px) {
    .form-row {
        grid-template-columns: 1fr;
    }

    .step-indicator {
        gap: 0.1rem;
    }

    .step {
        min-width: 60px;
    }

    .step__label {
        font-size: 0.65rem;
    }

    .step__connector {
        width: 1rem;
    }
}
