@namespace sv_b99e077589b24c00b279ad89750fbce4.Components.Pages.ApplySteps

<div class="work-entry">
    <div class="work-entry__header">
        <h4>Position @(Index + 1)</h4>
        @if (CanRemove)
        {
            <button type="button" class="btn btn--danger btn--small" @onclick="OnRemove">Remove</button>
        }
    </div>

    <div class="form-row">
        <div class="form-group">
            <label>Company Name *</label>
            <input type="text" value="@Entry.Company" @onchange="OnCompanyChanged" />
        </div>
        <div class="form-group">
            <label>Job Title *</label>
            <input type="text" value="@Entry.Title" @onchange="OnTitleChanged" />
        </div>
    </div>

    <div class="form-row">
        <div class="form-group">
            <label>Start Date *</label>
            <input type="date" value="@Entry.StartDate.ToString("yyyy-MM-dd")" @onchange="OnStartDateChanged" />
        </div>
        <div class="form-group">
            <label>End Date</label>
            <input type="date" value="@Entry.EndDate?.ToString("yyyy-MM-dd")" disabled="@Entry.IsCurrent" @onchange="OnEndDateChanged" />
            <label class="checkbox-label">
                <input type="checkbox" checked="@Entry.IsCurrent" @onchange="OnIsCurrentChanged" />
                Currently working here
            </label>
        </div>
    </div>

    <div class="form-group">
        <label>Description</label>
        <textarea rows="3" value="@Entry.Description" @onchange="OnDescriptionChanged"></textarea>
    </div>
</div>

@code {
    [Parameter, EditorRequired]
    public WorkEntryModel Entry { get; set; } = default!;

    [Parameter]
    public int Index { get; set; }

    [Parameter]
    public bool CanRemove { get; set; }

    [Parameter]
    public EventCallback<WorkEntryModel> OnEntryChanged { get; set; }

    [Parameter]
    public EventCallback OnRemove { get; set; }

    private Task OnCompanyChanged(ChangeEventArgs e)
    {
        Entry.Company = (string?)e.Value ?? "";
        return OnEntryChanged.InvokeAsync(Entry);
    }

    private Task OnTitleChanged(ChangeEventArgs e)
    {
        Entry.Title = (string?)e.Value ?? "";
        return OnEntryChanged.InvokeAsync(Entry);
    }

    private Task OnStartDateChanged(ChangeEventArgs e)
    {
        if (DateTime.TryParse((string?)e.Value, out var date))
            Entry.StartDate = date;
        return OnEntryChanged.InvokeAsync(Entry);
    }

    private Task OnEndDateChanged(ChangeEventArgs e)
    {
        Entry.EndDate = string.IsNullOrEmpty((string?)e.Value) ? null : DateTime.TryParse((string)e.Value!, out var d) ? d : null;
        return OnEntryChanged.InvokeAsync(Entry);
    }

    private Task OnIsCurrentChanged(ChangeEventArgs e)
    {
        Entry.IsCurrent = (bool?)e.Value ?? false;
        if (Entry.IsCurrent) Entry.EndDate = null;
        return OnEntryChanged.InvokeAsync(Entry);
    }

    private Task OnDescriptionChanged(ChangeEventArgs e)
    {
        Entry.Description = (string?)e.Value ?? "";
        return OnEntryChanged.InvokeAsync(Entry);
    }

    public class WorkEntryModel
    {
        public string Company { get; set; } = "";
        public string Title { get; set; } = "";
        public DateTime StartDate { get; set; } = DateTime.Today;
        public DateTime? EndDate { get; set; }
        public bool IsCurrent { get; set; }
        public string Description { get; set; } = "";
    }
}

